frappe.web_form.after_load = () => {
  const urlParams = new URLSearchParams(window.location.search);
  const shop_id = urlParams.get("shop");

  if (shop_id) {
    frappe.call({
      method: "frappe.client.get",
      args: {
        doctype: "Shop At Airport",
        name: shop_id, // This is doc.name, not shop_name
      },
      callback: function (r) {
        if (!r.exc && r.message) {
          const shop_data = r.message;

          // Fill your Lease Shop form fields
          frappe.web_form.set_value("shop_name", shop_data.shop_name || "");
        //   frappe.web_form.set_value("shop_number", shop_data.shop_number || "");
        //   frappe.web_form.set_value("area", shop_data.area || 0);
        //   frappe.web_form.set_value("monthly_rent", shop_data.monthly_rent || 0);

        //   // If you have a Link field in Lease Shop to reference Shop At Airport
        //   frappe.web_form.set_value("shop_at_airport", shop_id);
        } else {
          frappe.msgprint("Shop not found: " + shop_id);
        }
      }
    });
  }


//     frappe.call({
