//         doctype: "Shop At Airport",
//         name: shop,
//       },
//       callback: function (r) {
//         if (!r.exc && r.message) {
//           const shop_data = r.message;
//           frappe.web_form.set_value("monthly_rent", shop_data.monthly_rent);
//           frappe.web_form.set_value("area", shop_data.area);
//         }
//       }
//     });
//   }

  const disablePastDates = () => {
    const leaseStart = document.querySelector('input[data-fieldname="lease_start_date"]');
    if (leaseStart) {
      const today = new Date().toISOString().split("T")[0];
      leaseStart.setAttribute("min", today);
    } else {
      setTimeout(disablePastDates, 200);
    }
  };
  disablePastDates();

  // Active validation + auto-calculation
  frappe.web_form.on("lease_start_date", (field, value) => {
    if (value) {
      const selected = frappe.datetime.str_to_obj(value);
      const today = frappe.datetime.str_to_obj(frappe.datetime.get_today());

      if (selected < today) {
        frappe.msgprint("You cannot select a past date for lease start.");
        frappe.web_form.set_value("lease_start_date", "");
        frappe.web_form.set_value("lease_end_date", "");
        return;
      }

      // Add 1 year and set lease_end_date
      const end = new Date(selected);
      end.setFullYear(end.getFullYear() + 1);
      const formatted = frappe.datetime.obj_to_str(end).split(" ")[0];
      frappe.web_form.set_value("lease_end_date", formatted);
    }
  });
};
